// Command thirdparty writes THIRD_PARTY_LICENSES.txt: the licences of every
// module linked into the released agent binary (linux/amd64 + linux/arm64,
// the `make dist` build), with their licence/notice files verbatim.
//
//	go run ./cmd/thirdparty -o THIRD_PARTY_LICENSES.txt   (make third-party)
//
// The module set is `go list -deps` of the main package (exactly the modules
// that contribute linked packages; tests and tools are excluded). Licence
// files are read from the module cache (go.sum-verified), classified by
// their text, and checked against an allow-list: an unrecognised or
// disallowed licence fails the run instead of being guessed. The output is
// deterministic (sorted, no dates), so CI regenerates and diffs it
// (`make check-third-party`). Standard library only.
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"slices"
	"sort"
	"strings"
)

// targets are the platforms `make dist` releases (DIST_ARCHS).
var targets = [][2]string{{"linux", "amd64"}, {"linux", "arm64"}}

// allowed: licences a linked module may carry. The binary as a whole is
// GPL-3.0-or-later as soon as a GPL-3.0-or-later module is linked (R19);
// everything here is compatible with that.
var allowed = map[string]bool{
	"MIT":              true,
	"ISC":              true,
	"BSD-2-Clause":     true,
	"BSD-3-Clause":     true,
	"Apache-2.0":       true,
	"MPL-2.0":          true,
	"GPL-3.0-or-later": true,
	"LGPL-3.0-only WITH LGPL-3.0-linking-exception": true,
}

type module struct {
	Path, Version string
	Dir           string
	Files         []licFile
	License       string // SPDX-style expression (AND of the files' licences)
}

type licFile struct {
	Name    string
	Text    []byte
	License string // "" for NOTICE/PATENTS files
}

func main() {
	out := flag.String("o", "", "output file (default stdout)")
	flag.Parse()
	text, err := generate()
	if err != nil {
		fmt.Fprintln(os.Stderr, "thirdparty:", err)
		os.Exit(1)
	}
	if *out == "" {
		os.Stdout.Write(text)
		return
	}
	if err := os.WriteFile(*out, text, 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "thirdparty:", err)
		os.Exit(1)
	}
}

func generate() ([]byte, error) {
	mods, err := linkedModules()
	if err != nil {
		return nil, err
	}
	var problems []string
	for _, m := range mods {
		if err := m.readLicenses(); err != nil {
			problems = append(problems, err.Error())
		}
	}
	if len(problems) > 0 {
		return nil, errors.New(strings.Join(problems, "\n  "))
	}
	own, err := os.ReadFile("LICENSE")
	if err != nil {
		return nil, err
	}
	goroot, err := goEnv("GOROOT")
	if err != nil {
		return nil, err
	}
	std := &module{Path: "Go standard library", Version: "(toolchain per go.mod)", Dir: goroot}
	if err := std.readLicenses(); err != nil {
		return nil, err
	}
	gpl := slices.ContainsFunc(mods, func(m *module) bool {
		return strings.Contains(m.License, "GPL-3.0-or-later") && !strings.Contains(m.License, "LGPL")
	})

	var b bytes.Buffer
	w := func(format string, a ...any) { fmt.Fprintf(&b, format, a...) }
	w("akari-agent: licences of the released binary\n")
	w("Generated by `make third-party` (cmd/thirdparty) from `go list -deps` for\n")
	w("linux/amd64 and linux/arm64. Do not edit; CI checks that it is current.\n")
	w("The same text is printed by `akari-agent -licenses`.\n\n")
	w("LICENSING OF THE BINARY\n\n")
	w("akari-agent's own source code is MIT licensed (first text below).\n")
	if gpl {
		w("The released binary statically links modules licensed GPL-3.0-or-later\n")
		w("(marked below; reached through xray-core's Shadowsocks support), so every\n")
		w("akari-agent binary is a combined work conveyed under the GNU General Public\n")
		w("License version 3 or (at your option) any later version (full text below).\n")
		w("Corresponding source: https://github.com/akari-projectX/akari-agent at the\n")
		w("tag or commit printed by `akari-agent -version`; go.mod/go.sum pin every\n")
		w("module, and `make dist` reproduces the release binary byte for byte.\n")
		w("The MIT licence of akari-agent's own files is unchanged by this.\n")
	} else {
		w("No GPL module is linked: the binary is distributed under the MIT licence\n")
		w("together with the third-party notices below.\n")
	}
	w("\nLINKED MODULES (%d + Go standard library)\n\n", len(mods))
	width := 0
	for _, m := range mods {
		width = max(width, len(m.Path)+1+len(m.Version))
	}
	for _, m := range mods {
		w("  %-*s  %s\n", width, m.Path+" "+m.Version, m.License)
	}
	w("  %-*s  %s\n", width, std.Path+" "+std.Version, std.License)

	// Texts, verbatim, each distinct text once (most of the Go and Apache
	// files are identical), in order of first appearance.
	type text struct {
		labels []string
		body   []byte
	}
	var texts []*text
	add := func(label string, body []byte) {
		for _, t := range texts {
			if bytes.Equal(t.body, body) {
				t.labels = append(t.labels, label)
				return
			}
		}
		texts = append(texts, &text{labels: []string{label}, body: body})
	}
	add("akari-agent (own code): LICENSE", own)
	if gpl {
		gplText, err := os.ReadFile("LICENSES/GPL-3.0.txt")
		if err != nil {
			return nil, err
		}
		add("GNU General Public License v3 (the licence of the combined binary): LICENSES/GPL-3.0.txt", gplText)
	}
	for _, m := range append(mods, std) {
		for _, f := range m.Files {
			add(m.Path+" "+m.Version+": "+f.Name, f.Text)
		}
	}
	w("\nLICENCE AND NOTICE TEXTS\n")
	for _, t := range texts {
		w("\n%s\n", strings.Repeat("=", 78))
		for _, l := range t.labels {
			w("%s\n", l)
		}
		w("%s\n\n", strings.Repeat("-", 78))
		body := bytes.TrimRight(t.body, "\n\r\t ")
		b.Write(body)
		b.WriteByte('\n')
	}
	return b.Bytes(), nil
}

// linkedModules: the union over targets of the modules of every package the
// main package links (the main module itself excluded).
func linkedModules() ([]*module, error) {
	seen := map[string]*module{}
	for _, t := range targets {
		cmd := exec.Command("go", "list", "-deps",
			"-f", `{{with .Module}}{{if not .Main}}{{.Path}} {{.Version}}{{end}}{{end}}`, ".")
		cmd.Env = append(os.Environ(), "GOOS="+t[0], "GOARCH="+t[1], "CGO_ENABLED=0", "GOFLAGS=-mod=readonly")
		cmd.Stderr = os.Stderr
		out, err := cmd.Output()
		if err != nil {
			return nil, fmt.Errorf("go list (%s/%s): %w", t[0], t[1], err)
		}
		sc := bufio.NewScanner(bytes.NewReader(out))
		for sc.Scan() {
			f := strings.Fields(sc.Text())
			if len(f) != 2 {
				continue
			}
			if _, ok := seen[f[0]]; !ok {
				seen[f[0]] = &module{Path: f[0], Version: f[1]}
			}
		}
	}
	mods := make([]*module, 0, len(seen))
	paths := make([]string, 0, len(seen))
	for p, m := range seen {
		mods = append(mods, m)
		paths = append(paths, p)
	}
	sort.Slice(mods, func(i, j int) bool { return mods[i].Path < mods[j].Path })
	// Module directories (a replace directive's target, if any).
	cmd := exec.Command("go", append([]string{"list", "-m", "-json"}, paths...)...)
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("go list -m: %w", err)
	}
	dec := json.NewDecoder(bytes.NewReader(out))
	for dec.More() {
		var j struct {
			Path, Version, Dir string
			Replace            *struct{ Path, Version, Dir string }
		}
		if err := dec.Decode(&j); err != nil {
			return nil, err
		}
		m := seen[j.Path]
		if m == nil {
			continue
		}
		m.Dir = j.Dir
		if j.Replace != nil {
			m.Dir = j.Replace.Dir
			m.Version = strings.TrimSpace(m.Version + " => " + j.Replace.Path + " " + j.Replace.Version)
		}
	}
	for _, m := range mods {
		if m.Dir == "" {
			return nil, fmt.Errorf("%s: module not in the module cache (go mod download)", m.Path)
		}
	}
	return mods, nil
}

var licName = regexp.MustCompile(`(?i)^(licen[cs]e|copying|notice|patents)([.-][a-z0-9.-]*)?$`)

func (m *module) readLicenses() error {
	ents, err := os.ReadDir(m.Dir)
	if err != nil {
		return fmt.Errorf("%s: %w", m.Path, err)
	}
	var lics []string
	for _, e := range ents {
		if !e.Type().IsRegular() || !licName.MatchString(e.Name()) {
			continue
		}
		body, err := os.ReadFile(filepath.Join(m.Dir, e.Name()))
		if err != nil {
			return fmt.Errorf("%s: %w", m.Path, err)
		}
		f := licFile{Name: e.Name(), Text: body}
		up := strings.ToUpper(e.Name())
		if !strings.HasPrefix(up, "NOTICE") && !strings.HasPrefix(up, "PATENTS") {
			ids := classify(body)
			if len(ids) == 0 {
				return fmt.Errorf("%s: %s: licence text not recognised (classify it in cmd/thirdparty)", m.Path, e.Name())
			}
			for _, id := range ids {
				if !allowed[id] {
					return fmt.Errorf("%s: %s: licence %s is not on the allow-list", m.Path, e.Name(), id)
				}
				if !slices.Contains(lics, id) {
					lics = append(lics, id)
				}
			}
			f.License = strings.Join(ids, " AND ")
		}
		m.Files = append(m.Files, f)
	}
	if len(lics) == 0 {
		return fmt.Errorf("%s: no licence file in %s", m.Path, m.Dir)
	}
	m.License = strings.Join(lics, " AND ")
	return nil
}

// classify names the licences whose text appears in a licence file (a file
// may concatenate several, e.g. klauspost/compress). Matching is on
// lowercased, whitespace-collapsed text, by phrases specific to each
// licence; the copyleft families are checked first because their texts
// mention one another.
func classify(raw []byte) []string {
	s := strings.Join(strings.Fields(strings.ToLower(string(raw))), " ")
	has := func(p string) bool { return strings.Contains(s, p) }
	var ids []string
	switch {
	case has("gnu lesser general public license version 3") || has("licensed under the lgplv3"):
		if has("special exception") && has("links statically or dynamically") {
			ids = append(ids, "LGPL-3.0-only WITH LGPL-3.0-linking-exception")
		} else {
			ids = append(ids, "LGPL-3.0")
		}
	case has("gnu general public license as published by the free software foundation, either version 3 of the license, or (at your option) any later version") &&
		!has("terms and conditions"):
		// The licence notice alone (sagernet/sing*): v3 or later.
		ids = append(ids, "GPL-3.0-or-later")
	case has("gnu general public license version 3, 29 june 2007"):
		// The bare GPL text says nothing about "or later": decide by hand.
		ids = append(ids, "GPL-3.0")
	}
	if has("mozilla public license version 2.0") || has("mozilla public license, version 2.0") {
		ids = append(ids, "MPL-2.0")
	}
	if has("apache license") && has("version 2.0, january 2004") {
		ids = append(ids, "Apache-2.0")
	}
	if has("permission is hereby granted, free of charge, to any person obtaining a copy") {
		ids = append(ids, "MIT")
	}
	if has("permission to use, copy, modify, and/or distribute this software for any purpose with or without fee is hereby granted") {
		ids = append(ids, "ISC")
	}
	if has("redistribution and use in source and binary forms, with or without modification, are permitted") {
		if has("neither the name") || has("names of its contributors") || has("name of the copyright holder") {
			ids = append(ids, "BSD-3-Clause")
		} else {
			ids = append(ids, "BSD-2-Clause")
		}
	}
	return ids
}

func goEnv(name string) (string, error) {
	out, err := exec.Command("go", "env", name).Output()
	return strings.TrimSpace(string(out)), err
}
